/**
 * Block manifest: the machine-readable contract of one block type (item) for a catalog and a page builder. The contract
 * is generated by codegen-x/ui8kit (packages/prototypes) and synced into `src/generated/contracts/<item>/<n>.json`
 * (`scripts/sync-codegen.ts`); this file only types it and adds the builder helpers.
 *
 *   item      stable block type id (`hero-simple`); a saved block is `{ id, item, variant, options?, props }`
 *   model     the content model of `props` (`hero@1`), shared by every variant
 *   places    where each value is drawn: a place binds JSON-pointer templates (`*` = list index) to one spot
 *   variants  layout-only alternatives (axes); any valid `props` renders fully in every variant
 *   settings  instance options next to the variant: `level` (heading level 1–3), `landmarkLabel`
 */
export const BLOCK_CATEGORIES = [
  "hero",
  "features",
  "team",
  "cta",
  "pricing",
  "content",
  "media",
  "nav",
  "footer",
  "form",
  "social",
] as const;
export type BlockCategory = (typeof BLOCK_CATEGORIES)[number];

/** How a block draws: `wireframe` = shapes only (the catalog feed, the default), `page` = real content from `props`. */
export const MODES = ["wireframe", "page"] as const;
export type Mode = (typeof MODES)[number];

export const PLACE_KINDS = ["badge", "heading", "text", "action", "media"] as const;
export type PlaceKind = (typeof PLACE_KINDS)[number];

export type Place = {
  /** unique within the block (`action`, `members.title`) */
  place: string;
  kind: PlaceKind;
  /** JSON-pointer templates of the values drawn here; `*` is the list index of the instance */
  fields: string[];
  /** a place repeated per list item: the list field it repeats over (`members`) */
  list?: string;
};

export type BlockVariant = {
  id: string;
  label: string;
  /** Layout axes only (media side, column count, surface). Never content. Passed to the organism as props. */
  axes: Record<string, string>;
};

export type Setting = { type: string; default?: unknown };

/** The generated contract (`src/generated/contracts/<item>/<version>.json`). */
export type Contract = {
  item: string;
  version: number;
  block: string;
  organism: string;
  line: string;
  model: string;
  modelSchema: string;
  axes: Record<string, string[]>;
  defaults: Record<string, string>;
  variants: BlockVariant[];
  defaultVariant: string;
  settings: Record<string, Setting>;
  modes: Mode[];
  defaultMode: Mode;
  places: Place[];
  wireframe: { items: number };
};

export type BlockManifest = Contract & {
  /** stable block type id = `item` of a saved block */
  id: string;
  category: BlockCategory;
};

export type TitleLevel = 1 | 2 | 3;
export const TITLE_LEVELS: readonly TitleLevel[] = [1, 2, 3];

/** Instance options: presentation choices per placed block (not content, not a variant axis). */
export type BlockOptions = { level?: TitleLevel; landmarkLabel?: string };

/**
 * A block as a builder saves it on a page. `id` is the instance (also the heading id prefix), `item` the block type,
 * `variant` the layout, `options` the settings, `props` the content (valid for the item's model).
 */
export type BlockInstance<P = Record<string, unknown>> = {
  id: string;
  item: string;
  variant: string;
  options?: BlockOptions;
  props: P;
};

export function defaultVariant(block: BlockManifest): BlockVariant {
  return block.variants.find((v) => v.id === block.defaultVariant) ?? block.variants[0]!;
}
export const defaultVariantId = (block: BlockManifest): string => defaultVariant(block).id;
export function resolveVariant(block: BlockManifest, id: string | undefined): BlockVariant {
  return block.variants.find((v) => v.id === id) ?? defaultVariant(block);
}

/** The props of the generated organism for one saved instance: axes of the variant, settings, content, id and mode. */
export function instanceProps(block: BlockManifest, instance: BlockInstance<unknown>, mode: Mode = block.defaultMode): Record<string, unknown> {
  const content = (instance.props ?? {}) as Record<string, unknown>;
  return { ...resolveVariant(block, instance.variant).axes, ...instance.options, ...content, id: instance.id, mode };
}

/** The props of a catalog (wireframe) tile: no content, only the layout of the variant. */
export function wireframeProps(block: BlockManifest, variantId: string): Record<string, unknown> {
  return { ...resolveVariant(block, variantId).axes, id: `${block.id}-${variantId}`, mode: "wireframe" };
}

export function placeOf(block: BlockManifest, id: string): Place {
  const p = block.places.find((x) => x.place === id);
  if (!p) throw new Error(`${block.id}: no place ${id}`);
  return p;
}

/** The attributes a place instance carries in page mode: `data-place` (place id) and `data-field` (concrete pointers). */
export type PlaceBinding = { place: string; field: string };

/** `bind(team, "members.title", 1)` → `{ place: "members.title", field: "/members/1/title" }`. */
export function bind(block: BlockManifest, id: string, ...indices: number[]): PlaceBinding {
  const p = placeOf(block, id);
  const resolve = (template: string) => {
    let i = 0;
    return template.replace(/\*/g, () => String(indices[i++] ?? 0));
  };
  return { place: p.place, field: p.fields.map(resolve).join(" ") };
}

/** Which places draw a value (inspector: from a clicked or edited pointer back to its spots). */
export function placesFor(block: BlockManifest, pointerTemplate: string): Place[] {
  return block.places.filter((p) => p.fields.includes(pointerTemplate));
}
